import java.util.*;
import java.io.*;

public class Main {
    static final int MOD1 = 998244353;
    static final int MOD2 = 1000000007;
    static final int NN = 1000100;
    static List<Integer>[] s = new ArrayList[7];
    static long[] sum = new long[7];
    static int[] L = new int[NN];
    static long NTH;

    static {
        for (int i = 1; i <= 6; i++) {
            s[i] = new ArrayList<>();
        }
    }

    static long D(long x, long y) {
        return ((x - y) % MOD1 + MOD1) % MOD1;
    }

    static long nxt(long val, long n) {
        if (val * 10 <= n) {
            return val * 10;
        } else {
            val++;
            if (val <= n) {
                while (val % 10 == 0) {
                    val /= 10;
                }
            } else {
                val = (val - 1) / 10 + 1;
                while (val % 10 == 0) {
                    val /= 10;
                }
            }
        }
        return val;
    }

    static void pre() {
        long val = 0;
        int len = 1;
        int nth = 1;
        for (int i = 1; i <= 1111110; i++) {
            s[len].add((int) D(nth, val));
            nth++;
            if (len < 6) {
                len++;
                val *= 10;
            } else {
                val++;
                while (val % 10 == 0) {
                    val /= 10;
                }
                len--;
            }
        }
        for (int i = 1; i <=6; i++) {
            Collections.sort(s[i]);
            for (int v : s[i]) {
                sum[i] = (sum[i] + v) % MOD2;
            }
        }
        int ed = 1, f = 0;
        for (int i = 1; i <= 1000000; i++) {
            if (i == ed) {
                ed *= 10;
                f++;
            }
            L[i] = f;
        }
    }

    static long calc(long val, long nth, long n) {
        long ans = 0;
        long st = val / 100;
        st++;
        while (st % 10 == 0) {
            st /= 10;
        }
        while (val != st) {
            ans = (ans + D(nth, val)) % MOD2;
            nth++;
            val = nxt(val, n);
        }
        NTH = nth;
        return ans;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        pre();

        long n = Long.parseLong(br.readLine());
        long ans = 0;
        long val = 1;
        long nth = 1;

        if (n < 10000000) {
            for (int i = 1; i <= n; i++) {
                ans = (ans + D(i, val)) % MOD2;
                if (i == n) break;
                val = nxt(val, n);
            }
            System.out.println(ans);
            return;
        }

        long N = n / 1000000;
        while (true) {
            ans = (ans + D(nth, val)) % MOD2;
            nth++;
            if (L[(int) val] == L[(int) N]) {
                if (val == N) {
                    ans = (ans + calc(val * 10, nth, n)) % MOD2;
                    nth = NTH;
                    break;
                }
                long v = val;
                for (int i = 1; i <= 6; i++) {
                    v *= 10;
                    long del = D(nth - 1, v);
                    int Nbound = lowerBound(s[i], (int) (MOD1 - del));
                    Nbound = Nbound - s[i].size();
                    ans = (ans + sum[i] + (long) Nbound * MOD1 % MOD2) % MOD2;
                    ans = (ans + MOD2) % MOD2;
                    ans = (ans + del * s[i].size() % MOD2) % MOD2;
                }
                nth += 1111110;
            }
            val = nxt(val, N);
        }

        long nFinal = 1;
        for (int i = 1; i <= L[(int) N] + 5; i++) {
            nFinal *= 10;
        }
        nFinal--;
        long N2 = nFinal / 1000000;

        val /= 10;
        val++;
        while (val % 10 == 0) {
            val /= 10;
        }

        while (val != 1) {
            ans = (ans + D(nth, val)) % MOD2;
            nth++;
            if (L[(int) val] == L[(int) N2]) {
                long v = val;
                for (int i = 1; i <= 6; i++) {
                    v *= 10;
                    long del = D(nth - 1, v);
                    int Nbound = lowerBound(s[i], (int) (MOD1 - del));
                    Nbound = Nbound - s[i].size();
                    ans = (ans + sum[i] + (long) Nbound * MOD1 % MOD2) % MOD2;
                    ans = (ans + MOD2) % MOD2;
                    ans = (ans + del * s[i].size() % MOD2) % MOD2;
                }
                nth += 1111110;
            }
            val = nxt(val, N2);
        }

        System.out.println(ans);
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) high = mid;
            else low = mid + 1;
        }
        return low;
    }
}
